"use client"

import React, { useEffect, useState } from 'react'

export default function NoSSR({ children }: { children: React.ReactNode }) {
    const [mounted, setMounted] = useState(false)

    useEffect(() => {
        setMounted(true)
    }, [])

    if (!mounted) {
        return null
    }

    return <>{children}</>
}
